using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
public sealed class AutoBackupOptions {public bool enabled;public string id=Guid.NewGuid().ToString("N"),folder="",lastFile="",lastError="";public int hours=24,keep=7;public long lastSuccess,lastAttempt;}
internal static class AutomaticBackups {
 internal static void Validate(Data d){if(d.settings.AutoBackup==null)d.settings.AutoBackup=new AutoBackupOptions();var o=d.settings.AutoBackup;Guid id;if(!Guid.TryParseExact(o.id,"N",out id)||!new[]{1,6,12,24,168}.Contains(o.hours)||o.keep<1||o.keep>30||(o.folder??"").Length>2000||(o.lastFile??"").Length>2500||(o.lastError??"").Length>4000||o.lastSuccess<0||o.lastSuccess>DateTime.MaxValue.Ticks||o.lastAttempt<0||o.lastAttempt>DateTime.MaxValue.Ticks||(o.enabled&&String.IsNullOrWhiteSpace(o.folder)))throw new InvalidDataException("Réglages de sauvegarde automatique invalides.");}
 internal static bool Due(AutoBackupOptions o,DateTime utc){return o.enabled&&(o.lastSuccess==0||utc.ToUniversalTime().Ticks-o.lastSuccess>=TimeSpan.FromHours(o.hours).Ticks)&&(o.lastAttempt==0||utc.ToUniversalTime().Ticks-o.lastAttempt>=TimeSpan.FromMinutes(15).Ticks);}
 internal static void CheckFolder(Store store,string folder){string target=Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string source=Path.GetFullPath(store.Root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(target.StartsWith(source,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Choisissez un dossier en dehors des données de cet espace.");}
 internal static string Create(Store store,string json,string folder,string id,int keep){Guid parsed;if(!Guid.TryParseExact(id,"N",out parsed)||keep<1||keep>30)throw new InvalidDataException("Réglages de rotation invalides.");CheckFolder(store,folder);Directory.CreateDirectory(folder);string prefix="MonEspace-auto-"+id+"-";string name=prefix+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8)+".mespace";string file=Path.Combine(folder,name);FullBackup.ExportSnapshot(store,file,json);var files=Directory.GetFiles(folder,prefix+"*.mespace").Where(f=>{string n=Path.GetFileNameWithoutExtension(f).Substring(prefix.Length);DateTime time;return n.Length==23&&n[14]=='-'&&DateTime.TryParseExact(n.Substring(0,14),"yyyyMMddHHmmss",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out time)&&n.Substring(15).All(c=>Uri.IsHexDigit(c));}).OrderByDescending(f=>String.Equals(f,file,StringComparison.OrdinalIgnoreCase)).ThenByDescending(File.GetLastWriteTimeUtc).ThenByDescending(f=>f,StringComparer.Ordinal).ToList();foreach(var old in files.Skip(keep)){if(!String.Equals(Path.GetDirectoryName(Path.GetFullPath(old)),Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Chemin de sauvegarde inattendu.");File.Delete(old);}return file;}
}
internal sealed partial class ModernWorkspace {
 void AutoBackupFailure(string message){var o=store.Value.settings.AutoBackup;o.lastError=(message??"").Substring(0,Math.Min(4000,(message??"").Length));NotificationCenter.Incident(store.Value,"backup","automatic","Sauvegarde automatique échouée",o.lastError);}
 bool autoBackupBusy;internal bool IsAutoBackupBusy{get{return autoBackupBusy;}}
 internal async void CheckAutomaticBackup(bool force=false){if(owner.IsPreview||autoBackupBusy||updateBusy||IsAttachmentBusy)return;var options=store.Value.settings.AutoBackup;if(!options.enabled||(!force&&!AutomaticBackups.Due(options,DateTime.UtcNow)))return;if(!FlushDeskNotes())return;try{options.lastAttempt=DateTime.UtcNow.Ticks;store.Save();}catch(Exception ex){AutoBackupFailure(ex.Message);return;}string json;try{json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Serialize(store.Value);}catch(Exception ex){AutoBackupFailure(ex.Message);return;}autoBackupBusy=true;string folder=options.folder,id=options.id;int keep=options.keep;try{string file=await Task.Run(()=>AutomaticBackups.Create(store,json,folder,id,keep));options=store.Value.settings.AutoBackup;if(options.id!=id)return;options.lastSuccess=DateTime.UtcNow.Ticks;options.lastFile=file;options.lastError="";store.Value.notices.RemoveAll(n=>n.kind=="backup"&&n.key=="backup/automatic");try{store.Save();}catch(Exception ex){options.lastError="Sauvegarde créée, mais son état n’a pas pu être enregistré : "+ex.Message;}}
 catch(Exception ex){options=store.Value.settings.AutoBackup;options.lastError=(ex.Message??"").Substring(0,Math.Min(4000,(ex.Message??"").Length));NotificationCenter.Incident(store.Value,"backup","automatic","Sauvegarde automatique échouée",options.lastError);try{store.Save();}catch{}}
 finally{autoBackupBusy=false;if(!owner.IsDisposed){RefreshNoticeBadge();if(selected=="Réglages"||selected=="Sauvegardes automatiques")Refresh();}}}
 void AutomaticBackupPage(StackPanel body){var options=store.Value.settings.AutoBackup;var folder=new TextBox{Text=options.folder,IsReadOnly=true};Field(body,"Dossier des sauvegardes complètes",folder);body.Children.Add(Btn("Choisir un dossier",delegate{using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Dossier des sauvegardes complètes de cet espace",SelectedPath=folder.Text})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)folder.Text=picker.SelectedPath;},false,true));var frequency=Combo(new[]{"Toutes les heures","Toutes les 6 heures","Toutes les 12 heures","Chaque jour","Chaque semaine"},new[]{"Toutes les heures","Toutes les 6 heures","Toutes les 12 heures","Chaque jour","Chaque semaine"}[Array.IndexOf(new[]{1,6,12,24,168},options.hours)]);Field(body,"Fréquence lorsque cet espace est ouvert",frequency);var retention=new TextBox{Text=options.keep.ToString(),MaxLength=2};Field(body,"Nombre de sauvegardes à conserver (1 à 30)",retention);var enabled=new CheckBox{Content="Activer les sauvegardes automatiques",IsChecked=options.enabled,Margin=new Thickness(0,8,0,12)};body.Children.Add(enabled);var error=T("",12,Accent);body.Children.Add(error);var save=Btn("Enregistrer ces réglages",delegate{try{int keep;if(!Int32.TryParse(retention.Text,out keep)||keep<1||keep>30)throw new InvalidDataException("Conservez entre 1 et 30 sauvegardes.");if(enabled.IsChecked==true)AutomaticBackups.CheckFolder(store,folder.Text);PersonalWorkflows.Change(store,()=>{var o=store.Value.settings.AutoBackup;o.folder=folder.Text;o.hours=new[]{1,6,12,24,168}[frequency.SelectedIndex];o.keep=keep;o.enabled=enabled.IsChecked==true;});Refresh();}catch(Exception ex){error.Text=ex.Message;}},true);save.IsEnabled=!autoBackupBusy;body.Children.Add(save);var now=Btn(autoBackupBusy?"Sauvegarde en cours…":"Sauvegarder maintenant",()=>CheckAutomaticBackup(true),false,true);now.IsEnabled=options.enabled&&!autoBackupBusy;body.Children.Add(now);body.Children.Add(T(options.lastSuccess==0?"Aucune sauvegarde automatique réussie pour le moment.":"Dernière réussite : "+new DateTime(options.lastSuccess,DateTimeKind.Utc).ToLocalTime().ToString("dd/MM/yyyy HH:mm"),13,Ink,new Thickness(0,16,0,8)));if(!String.IsNullOrEmpty(options.lastError))body.Children.Add(T(options.lastError,12,Accent));if(!String.IsNullOrEmpty(options.folder))body.Children.Add(Btn("Ouvrir le dossier",()=>Open(options.folder),false,true));body.Children.Add(T("Sauvegardes complètes : données, historique des notes, pièces jointes et MP3. Les dossiers épinglés et les fichiers externes ne sont pas copiés. Les connexions Google/Spotify restent locales et ne sont pas exportées. Les documents non enregistrés ne sont pas inclus. Les sauvegardes ne sont pas chiffrées : choisissez un dossier privé. Aucun service ne fonctionne après avoir quitté Mon espace.",11,Muted,new Thickness(0,16,0,0)));}
}
